function classifyChange(note){
  const m=/^(Nuevo|Novedad|Mejora|Corregido|Corrección|Correccion|Bug|Pendiente|Bug pendiente):\s*(.*)$/i.exec(String(note||''));
  if(!m)return {type:'Mejora',label:'Mejora',css:'imp',text:String(note||'')};
  const key=m[1].toLowerCase();
  if(key==='nuevo'||key==='novedad')return {type:'Novedad',label:'Nuevo',css:'new',text:m[2]};
  if(key==='corregido'||key==='corrección'||key==='correccion')return {type:'Corrección',label:'Corregido',css:'fix',text:m[2]};
  if(key==='bug'||key==='pendiente'||key==='bug pendiente')return {type:'Bug pendiente',label:'Bug pendiente',css:'bug',text:m[2]};
  return {type:'Mejora',label:'Mejora',css:'imp',text:m[2]};
}
function showLog(){
  const dl=d=>new Date(d+'T00:00').toLocaleDateString('es-CO',{day:'numeric',month:'short',year:'numeric'});
  const filters=[['Todos','all'],['Novedades','Novedad'],['Mejoras','Mejora'],['Correcciones','Corrección'],['Bugs pendientes','Bug pendiente']];
  const content=`<div class="vcur"><span>Versión actual</span><b>v${APP_VERSION}</b></div>
  <p class="mut" style="margin:10px 2px 12px">Consulta qué se agregó, qué se mejoró y qué errores se corrigieron o siguen pendientes.</p>
  <div class="vsearch"><input id="changeSearch" type="search" placeholder="Buscar por cambio, función o versión…" oninput="filterChangeLog()" aria-label="Buscar en actualizaciones"><select id="changeFilter" onchange="filterChangeLog()" aria-label="Filtrar tipo de actualización">${filters.map(([t,v])=>`<option value="${v}">${t}</option>`).join('')}</select></div>
  <div class="vfilter-count" id="changeCount" aria-live="polite"></div>
  <div id="changeResults">${renderChangeLog(CHANGELOG,'','all',dl)}</div>
  <p class="mut" style="margin-top:14px">La versión 5.1 incorpora a Panelita como mascota oficial. Tus fichas, citas, inventario, caja y preferencias se guardan en la nube (Firestore).</p>`;
  sheet('Versiones y actualizaciones',content);
  filterChangeLog();
}
function renderChangeLog(entries,query='',filter='all',dateLabel=d=>d){
  const q=String(query||'').trim().toLocaleLowerCase('es');
  let count=0;
  const html=entries.map((c,i)=>{
    const items=c.notas.map(n=>classifyChange(n)).filter(x=>(filter==='all'||x.type===filter)&&(!q||`${x.text} ${x.type} ${c.v} ${c.fecha}`.toLocaleLowerCase('es').includes(q)));
    if(!items.length)return '';
    count+=items.length;
    return `<details class="vlog" ${i===0?'open':''}><summary><b>v${e(c.v)}</b><small>${dateLabel(c.fecha)}</small>${i===0?'<span class="vt cur">Actual</span>':''}<span class="vlog-total">${items.length} ${items.length===1?'cambio':'cambios'}</span></summary><ul>${items.map(x=>`<li><span class="vt ${x.css}">${x.label}</span><span>${e(x.text.charAt(0).toUpperCase()+x.text.slice(1))}</span></li>`).join('')}</ul></details>`;
  }).join('');
  return {html:html||'<div class="emp flat"><b>No se encontraron actualizaciones</b><span>Prueba con otra búsqueda o cambia el filtro.</span></div>',count};
}
function filterChangeLog(){
  const input=document.getElementById('changeSearch'),select=document.getElementById('changeFilter'),target=document.getElementById('changeResults'),countEl=document.getElementById('changeCount');
  if(!input||!select||!target)return;
  const dl=d=>new Date(d+'T00:00').toLocaleDateString('es-CO',{day:'numeric',month:'short',year:'numeric'});
  const result=renderChangeLog(CHANGELOG,input.value,select.value,dl);
  target.innerHTML=result.html;
  if(countEl)countEl.textContent=`${result.count} ${result.count===1?'resultado':'resultados'}`;
}
