/* ---------- TEMA ---------- */
const TK='dulcePanelita.theme';
function applyTheme(t){
  document.documentElement.setAttribute('data-theme',t);
  document.querySelectorAll('[data-themeico]').forEach(b=>{b.innerHTML=t==='dark'?IC.sun:IC.moon});
  const meta=document.querySelector('meta[name="theme-color"]');
  if(meta)meta.setAttribute('content',t==='dark'?'#100B18':'#B99BD5');
}
function toggleTheme(){
  const cur=document.documentElement.getAttribute('data-theme')==='dark'?'dark':'light';
  const nxt=cur==='dark'?'light':'dark';
  applyTheme(nxt);
  try{localStorage.setItem(TK,nxt)}catch(e){}
  toast(nxt==='dark'?'Modo oscuro activado':'Modo claro activado','ok');
}
(function initTheme(){
  let saved='light';
  try{saved=localStorage.getItem(TK)||'light'}catch(e){}
  applyTheme(saved);
})();

