let D=null;
/* Los datos ya no se leen de localStorage: los carga Firestore (js/firebase.js) y llegan por DP.start() */
if(!D||typeof D!=='object')D={pets:[],svc:[],cit:[],caja:[],inv:[],compras:[],prec:[],pagos:[],meta:{m:0},perfil:{diplomas:[]},cfg:{}};

function assignMovementCodes(){
  const all=[...(D.svc||[]),...(D.caja||[])];
  const used=new Set(all.map(x=>x.codigo).filter(Boolean));
  let max=0;
  used.forEach(c=>{const m=String(c).match(/^DP-(\d+)$/i);if(m)max=Math.max(max,+m[1]||0)});
  const ordered=all.filter(x=>!x.codigo).sort((a,b)=>(a.ts||0)-(b.ts||0));
  ordered.forEach(x=>{let code;do{max++;code='DP-'+String(max).padStart(6,'0')}while(used.has(code));x.codigo=code;used.add(code)});
}
function nextMovementCode(){
  assignMovementCodes();
  let max=0;
  [...(D.svc||[]),...(D.caja||[])].forEach(x=>{const m=String(x.codigo||'').match(/^DP-(\d+)$/i);if(m)max=Math.max(max,+m[1]||0)});
  return 'DP-'+String(max+1).padStart(6,'0');
}
function movementTime(x){
  if(x.hora)return x.hora;
  if(x.ts){const d=new Date(x.ts);if(!isNaN(d))return d.toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit',hour12:false})}
  return 'No registrada';
}
function normalize(){
  ['pets','svc','cit','caja','inv','compras','prec','pagos'].forEach(k=>{if(!Array.isArray(D[k]))D[k]=[]});
  if(!D.meta||typeof D.meta!=='object')D.meta={m:0};
  if(!D.perfil||typeof D.perfil!=='object')D.perfil={};
  if(!Array.isArray(D.perfil.diplomas))D.perfil.diplomas=[];
  if(!Array.isArray(D.perfil.logros))D.perfil.logros=[];
  if(!D.cfg||typeof D.cfg!=='object')D.cfg={};
  D.pets.forEach(p=>{if(!p.tamano){const t=tamDe(p.peso);if(t)p.tamano=t}});
  D.inv.forEach(m=>{if(!Array.isArray(m.historial))m.historial=[]});
  if(!Array.isArray(D.pagos))D.pagos=[];
  const ts=m=>{if(!m.ts)m.ts=new Date((m.fecha||'2026-01-01')+'T12:00:00').getTime()||Date.now()};
  D.caja.forEach(ts);D.svc.forEach(ts);
  assignMovementCodes();

}

let _dirty=false;
function markDirty(){_dirty=true;const b=document.getElementById('saveBtn');if(b)b.classList.add('on')}
function cleanDirty(){_dirty=false;const b=document.getElementById('saveBtn');if(b)b.classList.remove('on')}
function snapshot(){/* sin copias locales: el respaldo vive en Firestore */}
function save(cb){
  const previous=Array.isArray(D.perfil.logros)?D.perfil.logros.slice():[];
  let unlocked=[];
  try{unlocked=typeof LOGROS!=='undefined'?collectNewAchievements():[]}catch(x){D.perfil.logros=previous}
  if(!window.DPCloud||!window.DPCloud.ready){D.perfil.logros=previous;toast('Sin conexión con la nube: inicia sesión para guardar','err');return false}
  markDirty();
  window.DPCloud.push(ok=>{
    if(ok){if(!window.DPCloud.pending)cleanDirty()}
    else toast('No se pudo guardar en la nube. Revisa tu conexión e inténtalo de nuevo','err');
    if(cb)cb(ok);
  });
  if(unlocked.length)queueAchievementCelebration(unlocked);return true
}
function manualSave(){save(ok=>{if(ok)toast('Datos guardados en la nube','ok')})}
