const pnS=x=>x.pet=='otro'?((x.petNombre||'').trim()||'Otro'):pn(x.pet);
const sLabel=x=>(x.items&&x.items.length)?x.items.map(i=>i.n).join(', '):(x.serv||'');
const sCat=x=>(x.items&&x.items[0]&&x.items[0].c)||x.cat||x.serv||'Otros';
const sIcon=x=>SI[sCat(x)]||'🐾';
