const MESES=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
const short=n=>{n=+n||0;return n>=1e6?(n/1e6).toFixed(n%1e6?1:0)+'M':n>=1e3?Math.round(n/1e3)+'k':String(n)};
const tamOpts=v=>'<option value="">Sin definir</option>'+TAMANOS.map(t=>`<option value="${t.k}" ${t.k==v?'selected':''}>${t.label} (${t.r})</option>`).join('');
function buildItems(F){const items=F.getAll('sv').map(i=>D.prec.find(x=>x.id==i)).filter(Boolean).map(x=>({id:x.id,n:x.servicio,c:x.categoria||'Otros'}));const o=(F.get('otro')||'').trim();if(o)items.push({n:o,c:catOf(o)});return items}
function pickSel(c){const it=c.items||[],ok=i=>i.id&&D.prec.some(p=>p.id==i.id);return{ids:it.filter(ok).map(i=>i.id),otro:it.length?it.filter(i=>!ok(i)).map(i=>i.n).join(', '):(c.serv||'')}}
function svcPicker(c={},noFree){const{ids,otro}=pickSel(c),g={};D.prec.forEach(p=>{const k=p.categoria||'Otros';(g[k]=g[k]||[]).push(p)});
const cats=SV.filter(k=>g[k]).concat(Object.keys(g).filter(k=>!SV.includes(k)));
return `<label>Servicios prestados (puedes elegir varios)</label>${cats.length?cats.map(k=>`<div class="x-lbl" style="margin-top:11px">${SI[k]||'🏷️'} ${e(k)}</div><div class="chips">${g[k].map(p=>`<label><input type="checkbox" name="sv" value="${p.id}" ${ids.includes(p.id)?'checked':''} onchange="calcPrecio()">${e(p.servicio)}</label>`).join('')}</div>`).join(''):'<div class="c on-card" style="margin-top:7px"><small>Aún no tienes servicios en el catálogo. Créalos en Servicios o escribe uno abajo.</small></div>'}
${noFree&&D.prec.length?`<input type="hidden" name="otro" value="${e(otro)}">`:fld('Otro servicio (si no está en la lista)','otro',otro)}`}
function calcPrecio(){const f=$('#sh form'),pi=$('#pIn'),box=$('#svcPriceRows');if(!f||!pi)return;
  const ps=f.querySelector('select[name=pet]'),hint=$('#pHint');if(!ps||!hint)return;
  const tam=ps.value=='otro'?((f.querySelector('select[name=tamotro]')||{}).value||''):tamPet(pet(ps.value));
  const items=buildItems(new FormData(f));
  if(box){box.innerHTML=items.length?`<div class="x-lbl" style="margin:12px 0 5px">Precio de cada servicio (editable)</div>${items.map((it,i)=>{const key=it.id||('otro:'+it.n),catalog=it.id?priceOf(D.prec.find(x=>x.id==it.id),tam):0,stored=C.itemPrices[key];const val=stored!==undefined?stored:catalog;return `<label style="display:flex;align-items:center;justify-content:space-between;gap:10px">${e(it.n)}<input type="number" min="0" step="1" inputmode="numeric" name="itemPrice" data-pricekey="${e(key)}" value="${val}" style="width:145px;margin:0;text-align:right" oninput="calcPrecioTotal()"></label>`}).join('')}`:'<small style="display:block;margin-top:9px">Selecciona los servicios para asignar sus precios.</small>'}
  calcPrecioTotal();hint.textContent='Asigna o modifica el precio de cada servicio. El total se suma automáticamente.';
}
function calcPrecioTotal(){const f=$('#sh form'),pi=$('#pIn');if(!f||!pi)return;let total=0;f.querySelectorAll('input[name=itemPrice]').forEach(inp=>{total+=Math.max(0,+inp.value||0);C.itemPrices[ inp.dataset.pricekey ]=inp.value});pi.value=total||'';}
