function ingDia(ds){return sum(x=>x.fecha==ds)+D.caja.filter(x=>x.tipo=='ingreso'&&x.fecha==ds).reduce((a,x)=>a+(+x.monto||0),0)}
function ingMes(m){return sum(x=>x.fecha.startsWith(m))+D.caja.filter(x=>x.tipo=='ingreso'&&(x.fecha||'').startsWith(m)).reduce((a,x)=>a+(+x.monto||0),0)}
function gasMes(m){return D.caja.filter(x=>x.tipo!='ingreso'&&(x.fecha||'').startsWith(m)).reduce((a,x)=>a+(+x.monto||0),0)}
