function pesoChg(i){const t=tamDe(i.value),s=$('#tamSel'),h=$('#tamHint');if(!s)return;s.value=t;if(h)h.textContent=t?'Según el peso: '+tamLbl(t)+'.':'Se elige solo según el peso.'}
function pickPhoto(i){const f=i.files[0];if(!f)return;resizeImg(f,360,.72).then(u=>{$('#foto').value=u;$('#pv').src=u;$('#pv').style.display='block';markDirty()}).catch(()=>toast('No se pudo leer la imagen','err'))}
function capturePetLocation(btn){
  const status=$('#locStatus');
  if(!navigator.geolocation){if(status)status.textContent='Este navegador no permite obtener la ubicación.';toast('La ubicación no está disponible en este navegador','err');return}
  if(status)status.textContent='Solicitando permiso de ubicación…';
  if(btn){btn.disabled=true;btn.textContent='Obteniendo ubicación…'}
  navigator.geolocation.getCurrentPosition(pos=>{
    const lat=$('#petLat'),lon=$('#petLon');
    if(lat)lat.value=pos.coords.latitude.toFixed(7);
    if(lon)lon.value=pos.coords.longitude.toFixed(7);
    if(status)status.textContent='Ubicación guardada en esta ficha (precisión aproximada: '+Math.round(pos.coords.accuracy)+' m).';
    if(btn){btn.disabled=false;btn.textContent='✓ Ubicación obtenida'}
    markDirty();toast('Ubicación agregada a la ficha','ok');
  },err=>{
    const msg=err.code===1?'Permiso denegado. Puedes permitir la ubicación en los ajustes del navegador.':err.code===2?'No se pudo determinar la ubicación. Intenta de nuevo.':'La solicitud tardó demasiado. Intenta de nuevo.';
    if(status)status.textContent=msg;
    if(btn){btn.disabled=false;btn.textContent='◎ Usar mi ubicación actual'}
    toast('No se pudo obtener la ubicación','err');
  },{enableHighAccuracy:true,timeout:15000,maximumAge:60000});
}
function savePet(ev,id){ev.preventDefault();const F=new FormData(ev.target),o=Object.fromEntries(F);
if(!o.tamano&&o.peso)o.tamano=tamDe(o.peso);
if(id)Object.assign(pet(id),o);else D.pets.push({id:uid(),...o});save();closeSh();render();toast('Ficha guardada','ok')}
function petView(id){const p=pet(id);if(!p)return;
  const h=D.svc.filter(x=>x.pet==id).sort((a,b)=>b.fecha.localeCompare(a.fecha));
  const R=(a,b)=>`<div class="row"><span>${a}</span><span>${e(b||'—')}</span></div>`;
  const tl=tamLbl(tamPet(p));
  sheet(e(p.nombre),`<div class="c on-card" style="text-align:center;margin-top:4px">
    ${p.foto?`<img class="pv" src="${p.foto}" alt="">`:`<div class="av" style="margin:8px auto 0;width:96px;height:96px;font-size:46px;border-radius:12px">${p.especie=='Felino'?'🐱':'🐶'}</div>`}
    <div style="margin-top:9px"><span class="tg">${e(p.especie)}</span> ${p.enf=='Sí'?'<span class="tg alert">Cuidado</span>':''} ${p.vac=='No'?'<span class="tg off2">Vacuna pend.</span>':''}</div></div>
<div class="c"><div class="x-lbl" style="margin-bottom:4px">Tutor</div>${R('Registro',p.registro?fd(p.registro):'')}${R('Tutor',p.tutor)}${R('Contacto',p.tel)}${R('Dirección',p.dir)}${R('Ubicación GPS',p.lat&&p.lon?'Coordenadas guardadas':'No registrada')}${p.lat&&p.lon?`<div class="row"><span>Mapa</span><span><a target="_blank" rel="noopener" href="https://www.google.com/maps?q=${encodeURIComponent(p.lat+','+p.lon)}">Ver ubicación</a></span></div>`:''}${R('Emergencia',p.emerg)}</div>
<div class="c"><div class="x-lbl" style="margin-bottom:4px">Ficha clínica</div>${R('Sexo',p.sexo)}${R('Raza',p.raza)}${R('Nacimiento',p.nac)}${R('Peso',p.peso?p.peso+' kg':'')}${R('Tamaño',tl)}${R('Esterilizado',p.ster)}${R('Vacunas',p.vac)}${R('Desparasitado',p.desp)}${R('Enfermedad/alergia',p.enf=='Sí'?p.enfd||'Sí':'No')}${R('Alimentación',p.alim)}</div>
<div class="c"><div class="x-lbl" style="margin-bottom:4px">Historial</div>${h.length?h.slice(0,8).map(x=>`<div class="row"><span>${fd(x.fecha)} · ${sIcon(x)} ${e(sLabel(x))}</span><span>${cop(x.precio)}</span></div>`).join(''):'<small>Sin servicios todavía.</small>'}</div>
<div class="bar"><button class="b" style="flex:1" onclick="svcForm({pet:'${id}'})">Registrar movimiento</button><button class="b o" style="flex:1" onclick="citForm('${C.sel}','${id}')">Agendar cita</button></div>
<div class="bar"><button class="b o" style="flex:1" onclick="petForm('${id}')">Editar</button><button class="b r" style="flex:1" onclick="delPet('${id}')">Eliminar</button></div>`)}
function delPet(id){ask('¿Eliminar esta ficha? También se borran sus citas; los servicios ya registrados se conservan.',()=>{D.pets=D.pets.filter(p=>p.id!=id);D.cit=D.cit.filter(c=>c.pet!=id);save();closeSh();render();toast('Ficha eliminada')})}

/* ---------- CITAS ---------- */
function vCit(){
  const{y,m}=C,off=(new Date(y,m,1).getDay()+6)%7,dim=new Date(y,m+1,0).getDate();let c='';
  for(let i=0;i<off;i++)c+='<i></i>';
  for(let d=1;d<=dim;d++){const ds=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,cs=D.cit.filter(x=>x.fecha==ds),col=(off+d-1)%7;
    c+=`<button class="dy ${ds==C.sel?'sel':''} ${ds==today()?'td':''} ${col<2?'l':col>4?'r':''}" onclick="C.sel='${ds}';render()" aria-label="${fd(ds)}">${d}${cs.length?`<s>${cs.length}</s>`:''}${cs.length?`<div class="prev"><b>${fd(ds)}</b>${cs.slice(0,4).map(x=>`<i>${x.hora||'--:--'} ${sIcon(x)} ${e(pn(x.pet))}</i>`).join('')}${cs.length>4?`<i>+${cs.length-4} más…</i>`:''}</div>`:''}</button>`}
  const l=D.cit.filter(x=>x.fecha==C.sel).sort((a,b)=>(a.hora||'').localeCompare(b.hora||''));
  return `<div class="x-head"><div><h2>Citas</h2><small>${D.cit.filter(x=>x.fecha>=today()&&x.estado!=='completada').length} próximas · ${D.cit.filter(x=>x.estado==='completada').length} completadas en el historial</small></div><button class="b" onclick="citForm('${C.sel}')">${IC.plus} Cita</button></div>
<div class="c on-card"><div class="mh"><button onclick="mov(-1)" aria-label="Mes anterior">${IC.chevL}</button>${mesTxt(y,m)}<button onclick="mov(1)" aria-label="Mes siguiente">${IC.chevR}</button></div>
<div class="cal">${['L','M','M','J','V','S','D'].map(x=>`<em>${x}</em>`).join('')}${c}</div></div>
<div class="x-head" style="margin-top:14px"><div><h2 style="font-size:16px">${fdC(C.sel)}</h2><small>${l.length} ${l.length===1?'cita':'citas'}</small></div></div>
${l.length?l.map(x=>`<div class="c"><div class="pc">
  <div class="av" style="width:42px;height:42px;font-size:20px">${sIcon(x)}</div>
  <div><b>${x.hora||'Sin hora'} · ${e(pn(x.pet))}</b><small>${e(sLabel(x))}${x.nota?' · '+e(x.nota):''}</small>${x.estado==='completada'?`<small style="display:inline-flex;margin-top:5px;padding:3px 8px;border-radius:20px;background:rgba(46,158,99,.13);color:var(--pos);font-weight:700">✓ Completada${x.completadaEn?' · '+fd(x.completadaEn):''}</small>`:''}</div></div>
  <div class="bar" style="margin:10px 0 0">
    ${x.estado==='completada'?`<span class="mut" style="font-size:12px;align-self:center;flex:1">Guardada en el historial · sin movimiento generado</span>`:`<button class="b sm o" onclick="reagendarCit('${x.id}')">Reagendar</button>
    <button class="b sm o" onclick="waCit('${x.id}')">${IC.whatsapp} Recordar</button>
    <button class="b sm" onclick="completarCit('${x.id}')">✓ Completar cita</button>`}
    <button class="b sm r" onclick="delCit('${x.id}')">✕</button></div></div>`).join(''):`<div class="emp"><b>Día libre</b>No hay citas para esta fecha.<button class="b" onclick="citForm('${C.sel}')">Agendar</button></div>`}`;
}
function mov(d){C.m+=d;if(C.m<0){C.m=11;C.y--}if(C.m>11){C.m=0;C.y++}render()}
const MSG_DEF='Hola {tutor}, te recordamos la cita de {mascota} el {fecha} a las {hora} para {servicio}. — Dulce Panelita';
const MSG_TAGS=[['{tutor}','Tutor'],['{mascota}','Mascota'],['{fecha}','Fecha'],['{hora}','Hora'],['{servicio}','Servicio']];
const msgTpl=()=>((D.cfg&&D.cfg.msg)||'').trim()||MSG_DEF;
function msgFill(t,c,p){const v={tutor:p&&p.tutor||'',mascota:p&&p.nombre||pnS(c),fecha:fdL(c.fecha),hora:c.hora||'--:--',servicio:sLabel(c)};return t.replace(/\{(tutor|mascota|fecha|hora|servicio)\}/g,(m,k)=>v[k])}
function msgPrev(){const t=($('#msgTxt')||{}).value||MSG_DEF,c=D.cit.filter(x=>x.fecha>=today()&&x.estado!=='completada').sort((a,b)=>a.fecha.localeCompare(b.fecha))[0]||{pet:'',fecha:today(),hora:'10:00',items:[{n:'Baño'}]};
  const p=c.pet?pet(c.pet):{tutor:'Ana',nombre:'Luna'};const el=$('#msgPv');if(el)el.textContent=msgFill(t.trim()||MSG_DEF,c,p||{tutor:'Ana',nombre:'Luna'})}
function msgIns(tag){const t=$('#msgTxt');if(!t)return;const a=t.selectionStart??t.value.length,b=t.selectionEnd??a;t.value=t.value.slice(0,a)+tag+t.value.slice(b);t.focus();t.selectionStart=t.selectionEnd=a+tag.length;msgPrev()}
function msgForm(){sheet('Mensaje de recordatorio',`<form onsubmit="msgSave(event)">
<label>Mensaje que se envía por WhatsApp<textarea id="msgTxt" name="msg" rows="5" oninput="msgPrev()">${e(msgTpl())}</textarea></label>
<div class="x-lbl" style="margin-top:14px">Toca para insertar un dato</div>
<div class="chips">${MSG_TAGS.map(t=>`<button type="button" class="x-chip" onclick="msgIns('${t[0]}')">${t[1]}</button>`).join('')}</div>
<div class="x-lbl">Así se verá</div><div class="c on-card" style="margin-top:6px"><div id="msgPv" style="white-space:pre-wrap;font-size:14px"></div></div>
<div class="bar"><button class="b" style="flex:1">Guardar mensaje</button><button type="button" class="b o" onclick="msgReset()">Restaurar</button></div></form>`);msgPrev()}
function msgSave(ev){ev.preventDefault();const v=(ev.target.msg.value||'').trim();D.cfg.msg=(v&&v!==MSG_DEF)?v:'';save();closeSh();toast('Mensaje guardado','ok')}
function msgReset(){const t=$('#msgTxt');if(t){t.value=MSG_DEF;msgPrev()}}
function waCit(id){const c=D.cit.find(x=>x.id==id);if(!c)return;const p=pet(c.pet);
  let tel=(p&&p.tel||'').replace(/\D/g,'');
  if(!tel){toast('Esa mascota no tiene teléfono de contacto','warn');return}
  const txt=msgFill(msgTpl(),c,p);
  if(tel.length==10)tel='57'+tel;
  window.open(`https://wa.me/${tel}?text=${encodeURIComponent(txt)}`,'_blank');
}
function citForm(fecha,pre){if(!D.pets.length){toast('Primero crea una ficha de mascota','warn');go('pets');closeSh();return}
sheet('Nueva cita',`<form onsubmit="saveCit(event)">
<label>Mascota<select name="pet" required>${D.pets.map(p=>`<option value="${p.id}" ${p.id==pre?'selected':''}>${e(p.nombre)} (${e(p.tutor)})</option>`).join('')}</select></label>
${svcPicker()}
${fld('Fecha','fecha',fecha,'date','required')}${fld('Hora','hora','09:00','time')}${fld('Nota (opcional)','nota','')}
<button class="b w">Guardar cita</button></form>`)}
function saveCit(ev){ev.preventDefault();const F=new FormData(ev.target),f=Object.fromEntries(F),items=buildItems(F);if(!items.length){toast('Elige al menos un servicio','warn');return}
D.cit.push({id:uid(),pet:f.pet,fecha:f.fecha,hora:f.hora,nota:f.nota,items,serv:items.map(i=>i.n).join(', ')});C.sel=f.fecha;C.y=+f.fecha.slice(0,4);C.m=+f.fecha.slice(5,7)-1;save();closeSh();go('cit');toast('Cita guardada','ok')}
function reagendarCit(id){const c=D.cit.find(x=>x.id==id);if(!c)return;
sheet('Reagendar cita',`<form onsubmit="saveReag(event,'${id}')">
<label>Mascota<select disabled><option>${e(pn(c.pet))}</option></select></label>
${svcPicker(c)}
${fld('Nueva fecha','fecha',c.fecha,'date','required')}${fld('Nueva hora','hora',c.hora||'09:00','time','required')}${fld('Nota (opcional)','nota',c.nota||'')}
<button class="b w">Guardar cambios</button></form>`)}
function saveReag(ev,id){ev.preventDefault();const c=D.cit.find(x=>x.id==id),F=new FormData(ev.target),f=Object.fromEntries(F),items=buildItems(F);if(!items.length){toast('Elige al menos un servicio','warn');return}
Object.assign(c,{items,serv:items.map(i=>i.n).join(', '),fecha:f.fecha,hora:f.hora,nota:f.nota});C.sel=f.fecha;C.y=+f.fecha.slice(0,4);C.m=+f.fecha.slice(5,7)-1;save();closeSh();go('cit');toast('Cita reagendada','ok')}
function completarCit(id){const c=D.cit.find(x=>x.id==id);if(!c||c.estado==='completada')return;ask('¿Marcar esta cita como completada? Se conservará en el historial y no se creará ningún movimiento ni cobro.',()=>{c.estado='completada';c.completadaEn=today();save();render();toast('Cita completada y guardada en el historial','ok')})}
function delCit(id){ask('¿Borrar esta cita del historial? Esta acción no genera ni elimina movimientos.',()=>{D.cit=D.cit.filter(c=>c.id!=id);save();render();toast('Cita eliminada')})}

/* ---------- METAS ---------- */
const sum=f=>D.svc.filter(f).reduce((a,s)=>a+(+s.precio||0),0);
const gastosMes=m=>D.caja.filter(x=>x.tipo=='gasto'&&x.fecha.startsWith(m)).reduce((a,x)=>a+x.monto,0);
function fechasActivas(){return [...new Set([...D.svc.map(x=>x.fecha),...D.caja.map(x=>x.fecha)])].filter(Boolean).sort()}
function racha(){const s=new Set(fechasActivas());let n=0,d=new Date();if(!s.has(iso(d)))d.setDate(d.getDate()-1);while(s.has(iso(d))){n++;d.setDate(d.getDate()-1)}return n}
function mejorRacha(){const a=fechasActivas();let best=0,cur=0,prev=null;for(const f of a){if(prev&&(new Date(f)-new Date(prev))===864e5)cur++;else cur=1;prev=f;if(cur>best)best=cur}return best}
const LOGROS=[
  {k:'meta1',t:'Primera meta',d:'Cumple una meta',i:'target',fn:()=>{const m=today().slice(0,7);return +D.meta.m>0&&sum(s=>s.fecha.startsWith(m))>=+D.meta.m}},
  {k:'r7',t:'Racha de 7',d:'7 días seguidos',i:'flame',fn:()=>racha()>=7},
  {k:'r30',t:'Mes constante',d:'30 días seguidos',i:'medal',fn:()=>racha()>=30},
  {k:'p10',t:'10 pacientes',d:'10 fichas creadas',i:'paw',fn:()=>D.pets.length>=10},
  {k:'verde',t:'Mes en verde',d:'Cerrar sin pérdida',i:'leaf',fn:()=>{const m=today().slice(0,7);return ingMes(m)>0&&ingMes(m)>gasMes(m)}},
  {k:'cat',t:'Catálogo vivo',d:'5 servicios creados',i:'tag',fn:()=>D.prec.length>=5}
];
function logros(){return LOGROS.map(l=>({...l,ok:!!l.fn()}))}
let _achievementQueue=[],_achievementTimer=null;
function seedAchievementTracking(){
  const prior=new Set((Array.isArray(D.perfil.logros)?D.perfil.logros:[]).filter(x=>typeof x==='string'));
  LOGROS.forEach(l=>{if(l.fn())prior.add(l.k)});
  D.perfil.logros=[...prior];
}
function collectNewAchievements(){
  const prior=new Set((Array.isArray(D.perfil.logros)?D.perfil.logros:[]).filter(x=>typeof x==='string'));
  const unlocked=LOGROS.filter(l=>l.fn()&&!prior.has(l.k));
  D.perfil.logros=[...prior,...unlocked.map(l=>l.k)];
  return unlocked;
}
function queueAchievementCelebration(items){
  if(!items||!items.length)return;
  _achievementQueue.push(...items);
  if(_achievementTimer)return;
  _achievementTimer=setTimeout(showAchievementCelebration,520);
}
function showAchievementCelebration(){
  _achievementTimer=null;
  if(!_achievementQueue.length)return;
  const sh=document.getElementById('sh');
  if(sh&&sh.classList.contains('open')){_achievementTimer=setTimeout(showAchievementCelebration,450);return}
  const items=_achievementQueue.splice(0,_achievementQueue.length);
  const names=items.map(x=>x.t);
  sheet(items.length===1?'¡Nuevo logro desbloqueado!':'¡Nuevos logros desbloqueados!',`<div style="text-align:center;padding:8px 0 2px"><img class="dp-achieve-img" src="${PANELITA_CELEBRATE}" alt="Panelita celebrando contigo"><h2 style="text-align:center;color:var(--a);font-size:23px;margin:4px 0 5px">¡Lo lograste!</h2><p class="mut" style="text-align:center">${items.length===1?'Panelita está muy orgullosa de ti.':'¡Panelita está saltando de alegría por ti!'}</p></div><div class="dp-achieve-list">${items.map(x=>`<div class="dp-achieve-item"><span>✦</span><div><b>${e(x.t)}</b><small style="display:block;color:var(--mut);font-weight:600">${e(x.d)}</small></div></div>`).join('')}</div><p class="mut" style="text-align:center;font-size:12px">Cada pequeño logro hace crecer Dulce Panelita. 🐾💜</p><button class="b w" onclick="closeSh();setTimeout(showAchievementCelebration,180)">¡Gracias, Panelita!</button>`);
}
let TIM={on:false,acc:0,t0:0,iv:null};
function timStart(){if(TIM.on)return;TIM.on=true;TIM.t0=Date.now();TIM.iv=setInterval(timPaint,500);render()}
function timPause(){if(!TIM.on)return;TIM.acc+=Date.now()-TIM.t0;TIM.on=false;clearInterval(TIM.iv);TIM.iv=null;render()}
function timReset(){clearInterval(TIM.iv);TIM={on:false,acc:0,t0:0,iv:null};render()}
function timMs(){return TIM.acc+(TIM.on?Date.now()-TIM.t0:0)}
function timTxt(){const s=Math.floor(timMs()/1000);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
function timPaint(){const b=$('#timTxt');if(b)b.textContent=timTxt()}
function timRegistrar(){const m=Math.round(timMs()/6e4);timReset();svcForm({});setTimeout(()=>{const n=$('#svcNota');if(n&&m)n.value=`Duración: ${m} min`},90)}
function vMeta(){
  const n=new Date(),t=iso(n),m=t.slice(0,7),dim=new Date(n.getFullYear(),n.getMonth()+1,0).getDate();
  const ing=sum(s=>s.fecha.startsWith(m));
  const metaM=+D.meta.m||0, metaSem=metaM*12/52, metaDia=metaM/dim;
  const meses=[...new Set(D.svc.map(s=>s.fecha.slice(0,7)))].sort().reverse();
  const r=racha(),mr=mejorRacha(),L=logros();
  return `<div class="x-head"><div><h2>Metas</h2><small>Tu avance del mes</small></div></div>
<div class="racha"><span class="fl">${IC.flame}</span><div style="flex:1"><b>${r} ${r===1?'día':'días'} de racha</b><small>Mejor racha: ${mr} ${mr===1?'día':'días'}</small></div></div>
<div class="c"><label>Meta del mes (COP)<input type="number" inputmode="numeric" min="0" value="${metaM||''}" placeholder="Ej. 2.000.000" onchange="D.meta.m=+this.value;save();render()"></label>
<div class="row" style="margin-top:11px"><span>Equivale por semana</span><span>${cop(metaSem)}</span></div>
<div class="row"><span>Equivale por día (${dim} días)</span><span>${cop(metaDia)}</span></div>
${metaM?`<button class="b r w" onclick="delMeta()">Borrar meta</button>`:''}</div>
${metaM?`<div class="c"><div class="row" style="border:0;padding:0"><b style="font-family:Quicksand,sans-serif">Avance del mes</b><span class="big" style="font-size:19px">${cop(ing)}</span></div><div style="display:flex;justify-content:center;margin:14px 0 4px">${ring(ing/metaM*100,'var(--a)',116)}</div><div class="pr"><i style="width:${Math.min(100,ing/metaM*100)}%"></i></div><small>${ing>=metaM?'Meta cumplida':'Faltan '+cop(metaM-ing)+' · '+Math.round(ing/metaM*100)+'%'}</small></div>`:''}
<div class="c"><div class="ct"><b>Temporizador de servicio</b></div><small>Mide cuánto dura la atención.</small>
<div class="timer ${TIM.on?'on':''}">${IC.timer}<b id="timTxt">${timTxt()}</b>
${TIM.on?`<button onclick="timPause()">Pausar</button>`:`<button onclick="timStart()">${TIM.acc?'Seguir':'Iniciar'}</button>`}
${TIM.acc&&!TIM.on?`<button onclick="timRegistrar()">Registrar</button><button onclick="timReset()">✕</button>`:''}</div></div>
<div class="c"><div class="ct"><b>Insignias</b><small>${L.filter(x=>x.ok).length}/${L.length}</small></div>
<div class="lgr">${L.map(l=>`<div class="${l.ok?'':'lk'}"><span>${IC[l.i]||IC['map-pin']||''}</span><b>${l.t}</b><em>${l.d}</em></div>`).join('')}</div></div>
<div class="x-head" style="margin-top:16px"><div><h2 style="font-size:16px">Registro mensual</h2></div></div>
${meses.length?meses.map(mm=>{const i2=sum(s=>s.fecha.startsWith(mm));return `<div class="c tap" onclick="verMes('${mm}')"><div class="pc"><div class="av" style="width:42px;height:42px;background:var(--g2);color:var(--a)">${IC.cal}</div><div><b>${mesTxt(+mm.slice(0,4),+mm.slice(5,7)-1)}</b><small>Total: ${cop(i2)}</small></div>${IC.chevR}</div></div>`}).join(''):'<div class="emp"><b>Sin meses todavía</b>Los servicios que registres aparecerán aquí.</div>'}`;
}
function delMeta(){ask('¿Borrar la meta mensual actual?',()=>{D.meta.m=0;save();render();toast('Meta borrada')})}
function verMes(m){const svc=D.svc.filter(s=>s.fecha.startsWith(m)).sort((a,b)=>a.fecha.localeCompare(b.fecha));
const ing=svc.reduce((a,s)=>a+(+s.precio||0),0);
const gas=D.caja.filter(x=>x.tipo=='gasto'&&x.fecha.startsWith(m));
const gasT=gas.reduce((a,x)=>a+x.monto,0);
const neto=ing-gasT;
sheet('Detalle '+new Date(m+'-01T00:00').toLocaleDateString('es-CO',{month:'long',year:'numeric'}),`
<div class="vm"><h3>Servicios del mes</h3>${svc.length?svc.map(s=>`<div class="li"><span>${s.fecha.slice(8)} · ${e(pnS(s))} · ${e(sLabel(s))}</span><b>${cop(s.precio)}</b></div>`).join(''):'<small>Sin servicios.</small>'}</div>
<div class="vm"><h3>Ingresos</h3><div class="li"><span>Servicios</span><b class="pos">+${cop(ing)}</b></div></div>
<div class="vm"><h3>Egresos</h3>${gas.length?gas.map(x=>`<div class="li"><span>${x.fecha.slice(8)} · ${e(x.concepto)}</span><b class="neg">−${cop(x.monto)}</b></div>`).join(''):'<small>Sin egresos.</small>'}</div>
<div class="vm"><div class="tot"><span>Ganancia neta del mes</span><span style="color:${neto<0?'var(--neg)':'var(--pos)'}">${cop(neto)}</span></div></div>`)}

/* ---------- PRECIOS ---------- */
const TAMANOS=[
  {k:'miniatura',label:'Miniatura',r:'0–5 kg'},
  {k:'pequeno',label:'Pequeño',r:'5–10 kg'},
  {k:'mediano',label:'Mediano',r:'10–20 kg'},
  {k:'grande',label:'Grande',r:'20–35 kg'},
  {k:'gigante',label:'Gigante',r:'más de 35 kg'}
];
/* Tamaño según el peso. Un peso justo en el límite (5, 10, 20, 35) cuenta en el tamaño menor. */
function tamDe(kg){kg=parseFloat(String(kg??'').replace(',','.'));if(!(kg>0))return '';return kg<=5?'miniatura':kg<=10?'pequeno':kg<=20?'mediano':kg<=35?'grande':'gigante'}
const tamPet=p=>p?(p.tamano||tamDe(p.peso)):'';
const tamLbl=k=>{const t=TAMANOS.find(x=>x.k==k);return t?t.label:''};
const idTs=x=>{const n=parseInt(String(x.id||'').slice(0,-3),36);return n>1.5e12&&n<4e12?n:0};
function normPrecios(pr){const o={};TAMANOS.forEach(t=>o[t.k]=+(pr&&pr[t.k])||0);return o}
function vPrec(){
  const grupos={};
  [...D.prec].sort((a,b)=>idTs(b)-idTs(a)).forEach(p=>{const c=p.categoria||'Otros';(grupos[c]=grupos[c]||[]).push(p)});
  const cats=SV.filter(c=>grupos[c]).concat(Object.keys(grupos).filter(c=>!SV.includes(c)));
  const top=`<div class="x-head"><div><h2>Servicios</h2><small>${D.prec.length} en el catálogo</small></div><button class="b" onclick="precioForm()">${IC.plus} Servicio</button></div>`;
  if(!D.prec.length)return top+`<div class="emp"><b>Catálogo vacío</b>Crea tu primer servicio para agilizar los registros.<button class="b" onclick="precioForm()">Crear servicio</button></div>`;
  return top+cats.map(c=>{const arr=grupos[c];return `<div class="cat-group"><div class="cat-head"><b>${SI[c]||'🏷️'} ${e(c)}</b><span>${arr.length}</span></div>${arr.map(p=>{const pr=normPrecios(p.precios),gen=modoOf(p)=='general';return `<div class="pr-card"><div class="h"><b>${e(p.servicio)}</b><span style="display:flex;align-items:center;gap:5px"><button class="x" title="Subir dentro de la categoría" onclick="event.stopPropagation();moverElemento('prec','${p.id}',-1)">↑</button><button class="x" title="Bajar dentro de la categoría" onclick="event.stopPropagation();moverElemento('prec','${p.id}',1)">↓</button><span class="tg">${gen?'General':'Por tamaños'}</span></span></div>${p.desc?`<div class="desc">${e(p.desc)}</div>`:''}${gen?`<div style="margin-top:8px"><small>Precio</small><b class="big" style="font-size:19px">${cop(p.general)}</b></div>`:`<div class="prices">${TAMANOS.map(t=>`<div>${t.label}<b>${cop(pr[t.k])}</b></div>`).join('')}</div>`}<div class="bar" style="margin:9px 0 0"><button class="b sm o" style="flex:1" onclick="precioForm('${p.id}')">Editar</button><button class="b sm r" style="flex:1" onclick="delPrecio('${p.id}')">Eliminar</button></div></div>`}).join('')}</div>`}).join('');
}
function precioForm(id){const p=id?D.prec.find(x=>x.id==id)||{}:{},pr=normPrecios(p.precios),modo=id?modoOf(p):'general';
sheet(id?'Editar servicio':'Nuevo servicio',`<form onsubmit="savePrecio(event,'${id||''}')">
${fld('Servicio','servicio',p.servicio,'text','required')}
<label>Categoría<select name="categoria">${opts(SV,p.categoria)}</select></label>
${fld('Descripción','desc',p.desc,'text')}
<label>Tipo de precio<select name="modo" onchange="togModo(this.value)"><option value="general" ${modo=='general'?'selected':''}>Precio general (un solo valor)</option><option value="tamano" ${modo=='tamano'?'selected':''}>Precio por tamaños</option></select></label>
<div id="pg" ${modo=='general'?'':'style="display:none"'}>${fld('Precio general (COP)','general',p.general||'','number','min="0" inputmode="numeric"')}</div>
<div id="pt" ${modo=='tamano'?'':'style="display:none"'}><div class="x-lbl" style="margin-top:16px">Precio por tamaño (COP)</div>${TAMANOS.map(t=>fld(t.label+' ('+t.r+')',t.k,pr[t.k]||'','number','min="0" inputmode="numeric"')).join('')}</div>
<button class="b w">${id?'Guardar cambios':'Guardar servicio'}</button></form>`)}
function togModo(v){$('#pg').style.display=v=='general'?'':'none';$('#pt').style.display=v=='tamano'?'':'none'}
function savePrecio(ev,id){ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));
const precios={};TAMANOS.forEach(t=>precios[t.k]=+f[t.k]||0);
const o={servicio:f.servicio,categoria:f.categoria,desc:f.desc,modo:f.modo,general:+f.general||0,precios};
if(id)Object.assign(D.prec.find(x=>x.id==id),o);else D.prec.push({id:uid(),...o});
save();closeSh();render();toast(id?'Servicio actualizado':'Servicio agregado','ok')}
function delPrecio(id){ask('¿Eliminar este servicio del catálogo? Los movimientos ya registrados se conservan.',()=>{D.prec=D.prec.filter(p=>p.id!=id);save();render();toast('Servicio eliminado')})}

/* ---------- HISTORIAL ---------- */
function vSvc(){
  const m=today().slice(0,7);
  let l=[...D.svc].sort((a,b)=>b.fecha.localeCompare(a.fecha)||(b.ts||0)-(a.ts||0));
  if(VF!='all')l=l.filter(x=>sCat(x)==VF);
  const totMes=sum(x=>x.fecha.startsWith(m));
  let last='';
  const chips=[['all','Todo'],...SV.map(c=>[c,SI[c]+' '+c])];
  return `<div class="x-head"><div><h2>Historial</h2><small>Ingresos del mes: ${cop(totMes)}</small></div><button class="b" onclick="svcForm()">${IC.plus} Movimiento</button></div>
<div class="chips">${chips.map(c=>`<button class="x-chip ${VF==c[0]?'on':''}" onclick="VF='${c[0]}';render()">${c[1]}</button>`).join('')}</div>
${l.length?l.slice(0,90).map(x=>{const hd=x.fecha!=last?`<div class="x-head" style="margin:16px 0 8px"><div><h2 style="font-size:14px">${fdC(x.fecha)}</h2><small>${cop(sum(y=>y.fecha==x.fecha))} ese día</small></div></div>`:'';last=x.fecha;
return hd+`<div class="c"><div class="pc"><div class="av" style="width:42px;height:42px;font-size:20px">${sIcon(x)}</div><div><b>${e(pnS(x))}</b><small>${e(sLabel(x))} · ${e(x.codigo||'')}</small></div><b style="font-size:15px">${cop(x.precio)}</b></div>
<div class="bar" style="margin:9px 0 0"><button class="b sm o" style="flex:1" onclick="svcForm({id:'${x.id}'})">Editar</button><button class="b sm o" style="flex:1" onclick="printSvc('${x.id}')">${IC.print} Comprobante</button><button class="b sm r" onclick="delSvc('${x.id}')">✕</button></div></div>`}).join(''):'<div class="emp"><b>Sin movimientos</b>Registra el primero con el botón de arriba.<button class="b" onclick="svcForm()">Nuevo movimiento</button></div>'}`;
}
