function toggleSearch(){const h=document.querySelector('header');h.classList.toggle('sr');if(h.classList.contains('sr'))setTimeout(()=>$('#gq').focus(),30);else{$('#gres').classList.remove('on')}}
let _gr=[];
function gSearch(v){const box=$('#gres');v=(v||'').trim().toLowerCase();
  if(!v){box.classList.remove('on');box.innerHTML='';_gr=[];return}
  const has=(...a)=>a.join(' ').toLowerCase().includes(v),R=[];
  const matches=[...(D.svc||[]),...(D.caja||[])].filter(x=>String(x.codigo||'').toLowerCase().includes(v));
  matches.slice(0,8).forEach(x=>{
    const isSvc=(D.svc||[]).some(s=>s.id===x.id);
    R.push({g:'Movimientos por código',ic:`<span class="ki" style="background:#8E5BA626;color:#8E5BA6">${IC.print}</span>`,t:x.codigo,s:isSvc?`${pnS(x)} · ${sLabel(x)} · ${cop(x.precio)}`:`${x.concepto||'Movimiento'} · ${cop(x.monto||0)}`,f:()=>{if(isSvc)printSvc(x.id);else sheet('Movimiento',`<div class="c"><b>${e(x.codigo)}</b><p>${e(x.concepto||'Movimiento')}</p><p>${fdL(x.fecha)} · ${e(movementTime(x))}</p><b>${cop(x.monto||0)}</b></div>`)}});
  });

  [['Nueva cita','cita',()=>citForm(today())],['Nuevo movimiento','movimiento',()=>svcForm()],['Nueva mascota','mascota',()=>petForm()],['Nuevo material','material',()=>invForm()],['Nuevo servicio','catálogo',()=>precioForm()],['Ir a Caja','sección',()=>go('caja')],['Ir a Metas','sección',()=>go('meta')],['Respaldo','datos',()=>backup()],['Modo oscuro','tema',()=>toggleTheme()]]
   .filter(c=>has(c[0],c[1])).forEach(c=>R.push({g:'Acciones',ic:`<span class="ki" style="background:#8E5BA626;color:#8E5BA6">${IC.plus}</span>`,t:c[0],s:'Comando',f:c[2]}));
  D.pets.filter(p=>has(p.nombre,p.tutor,p.raza,p.tel)).sort((a,b)=>(b.registro||'').localeCompare(a.registro||'')).slice(0,5).forEach(p=>R.push({g:'Mascotas',ic:petAv(p.id,34),t:p.nombre,s:'Tutor: '+(p.tutor||'—'),f:()=>petView(p.id)}));
  D.cit.filter(c=>has(pn(c.pet),sLabel(c),c.nota)).sort((a,b)=>a.fecha.localeCompare(b.fecha)).slice(0,4).forEach(c=>R.push({g:'Citas',ic:`<span class="ki" style="background:#8E5BA626;color:#8E5BA6">${IC.cal}</span>`,t:pn(c.pet)+' · '+sLabel(c),s:fd(c.fecha)+(c.hora?' · '+c.hora:''),f:()=>openDay(c.fecha)}));
  D.prec.filter(p=>has(p.servicio,p.categoria,p.desc)).slice(0,4).forEach(p=>R.push({g:'Servicios',ic:`<span class="ki" style="background:#F2B88026;color:#C98A4B">${IC.tag}</span>`,t:p.servicio,s:p.categoria||'Otros',f:()=>go('prec')}));
  D.inv.filter(m=>has(m.nombre,m.categoria,m.prov)).sort((a,b)=>(b.compra||'').localeCompare(a.compra||'')).slice(0,4).forEach(m=>R.push({g:'Inventario',ic:`<span class="ki" style="background:#8FC9A326;color:#4E9B6E">${IC.box}</span>`,t:m.nombre,s:(m.cantidad||'—')+(m.agotado?' · Agotado':''),f:()=>invView(m.id)}));
  _gr=R;let last='',h='';
  R.forEach((r,i)=>{if(r.g!=last){h+=`<div class="gh">${r.g}</div>`;last=r.g}h+=`<button class="rs" onclick="gGo(${i})">${r.ic}<div><b>${e(r.t)}</b><small>${e(r.s)}</small></div></button>`});
  box.innerHTML=h||'<div class="gn">Sin resultados para «'+e(v)+'»</div>';box.classList.add('on')}
function gGo(i){const r=_gr[i];$('#gq').value='';$('#gres').classList.remove('on');$('#gres').innerHTML='';document.querySelector('header').classList.remove('sr');if(r)r.f()}
function notifs(){const t=today(),n=new Date(),man=iso(new Date(n.getFullYear(),n.getMonth(),n.getDate()+1)),L=[];
  const hoy=D.cit.filter(c=>c.fecha==t&&c.estado!=='completada'),mn=D.cit.filter(c=>c.fecha==man&&c.estado!=='completada'),pas=D.cit.filter(c=>c.fecha<t&&c.estado!=='completada');
  const vac=D.pets.filter(p=>p.vac=='No'),des=D.pets.filter(p=>p.desp=='No'),ago=D.inv.filter(x=>x.agotado),bd=D.pets.filter(p=>(p.nac||'').slice(5)==t.slice(5)&&p.nac);
  if(hoy.length)L.push({i:'cal',c:'#8E5BA6',t:plural(hoy.length,'cita para hoy','citas para hoy'),s:hoy.slice(0,3).map(c=>pn(c.pet)).join(', '),a:`closeSh();openDay('${t}')`});
  if(mn.length)L.push({i:'cal',c:'#4A6FD4',t:plural(mn.length,'cita para mañana','citas para mañana'),s:mn.slice(0,3).map(c=>pn(c.pet)).join(', '),a:`closeSh();openDay('${man}')`});
  if(pas.length)L.push({i:'clock',c:'#F2B880',t:plural(pas.length,'cita pasada sin marcar','citas pasadas sin marcar'),s:'Márcalas para que cuenten en tus ingresos',a:`closeSh();go('cit')`});
  if(bd.length)L.push({i:'spark',c:'#C98FD6',t:'Hoy cumple años '+bd.map(p=>p.nombre).join(', '),s:'Cumpleaños',a:`closeSh();go('pets')`});
  if(vac.length)L.push({i:'alert',c:'#4A6FD4',t:plural(vac.length,'mascota con vacunas pendientes','mascotas con vacunas pendientes'),s:vac.slice(0,3).map(p=>p.nombre).join(', '),a:`closeSh();go('pets')`});
  if(des.length)L.push({i:'alert',c:'#E8A9C4',t:plural(des.length,'mascota con desparasitación pendiente','mascotas con desparasitación pendiente'),s:des.slice(0,3).map(p=>p.nombre).join(', '),a:`closeSh();go('pets')`});
  if(ago.length)L.push({i:'box',c:'#F2B880',t:plural(ago.length,'material agotado','materiales agotados'),s:ago.slice(0,3).map(x=>x.nombre).join(', '),a:`closeSh();go('inv')`});
  return L}
